WITH remaining_keys AS (SELECT dept_id, job_title FROM employees EXCEPT ALL SELECT dept_id, job_title FROM employees WHERE dept_id = 9), kept_rows AS (SELECT s.* FROM employees s INNER JOIN remaining_keys k ON s.dept_id = k.dept_id AND s.job_title = k.job_title) SELECT level, SUM(salary) FILTER (WHERE job_title = 'Designer') AS designer_total_salary, PERCENTILE_APPROX(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, SIZE(COLLECT_SET(level)) AS num_levels, COUNT(*) AS row_count, SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list FROM kept_rows GROUP BY level ORDER BY designer_total_salary DESC
